function createScope() {
  const handlers = [];
  return {
    onDispose(fn) {
      handlers.push(fn);
    },
    async disposeAll() {
      const failures = [];
      for (const fn of handlers.splice(0).reverse()) {
        try {
          await fn();
        } catch (error) {
          failures.push(error);
        }
      }
      if (failures.length > 0) throw new AggregateError(failures, "disposal failed");
    },
  };
}

const scope = createScope();
scope.onDispose(() => console.log("connection closed"));
scope.onDispose(() => { throw new Error("unsubscribe failed"); });
scope.onDispose(() => console.log("timer cleared"));
try {
  await scope.disposeAll();
} catch (error) {
  console.log(`${error.errors.length} failure: ${error.errors.map((e) => e.message).join(", ")}`);
}

