import { PluginStartError } from "@zudojs/errors";

async function startPlugins(start, diagnostics) {
  try {
    await start();
  } catch (error) {
    const failed = diagnostics().plugins.find((p) => p.failed);
    if (!failed) throw error;
    throw new PluginStartError(`Plugin "${failed.plugin.name}" failed to start: ${error.message}`, failed.plugin.name, { cause: error });
  }
}

