const inFlight = new Set();
let accepting = true;
let ok = 0;
let failed = 0;

function submit(ms, fails = false) {
  if (!accepting) return "rejected";
  const job = new Promise((resolve, reject) => setTimeout(() => (fails ? reject(new Error("bounce")) : resolve()), ms))
    .then(() => void ok++, () => void failed++)
    .finally(() => inFlight.delete(job));
  inFlight.add(job);
  return "accepted";
}

async function stop() {
  accepting = false;
  const waiting = inFlight.size;
  await Promise.allSettled([...inFlight]);
  return waiting;
}

submit(20);
submit(5, true);
submit(10);
console.log("drained", await stop());
console.log(`done: ${ok} ok, ${failed} failed`);
console.log("after stop:", submit(5));

