import { createEventBus } from "@zudojs/events";

function toPluginEvents(bus) {
  const subscriptions = new Map();
  return {
    on(name, handler) {
      subscriptions.set(handler, bus.on(name, (event) => handler(event.payload)));
    },
    off(name, handler) {
      subscriptions.get(handler)?.unsubscribe();
      subscriptions.delete(handler);
    },
    emit(name, payload) {
      return bus.publishEvent({ type: name, payload });
    },
  };
}

const bus = createEventBus();
const events = toPluginEvents(bus);
const handler = (payload) => console.log("receipt for", payload.reference);
events.on("payment.succeeded", handler);
await events.emit("payment.succeeded", { reference: "ORD-7" });
events.off("payment.succeeded", handler);
