function register(plugin, allowed) {
  const denied = (plugin.metadata.capabilities ?? []).filter((c) => !allowed.includes(c));
  if (denied.length > 0) {
    throw new Error(`Plugin "${plugin.metadata.name}" requests capabilities that are not granted: ${denied.join(", ")}.`);
  }
  return `registered ${plugin.metadata.name}`;
}

